	if u == 0 {
		return i
	}
	i -= (bits.Len64(u|1)+traceVarintPayloadBits-1)/traceVarintPayloadBits + 1
	b[i] = tag
	p := i + 1
	for ; u >= traceVarintContBit; u >>= traceVarintPayloadBits {
		b[p] = byte(u) | traceVarintContBit
		p++
	}
	b[p] = byte(u)
	return i
